#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# learnaws: secrets for local dev (.env.local) and the Dokploy app.
cd "$(dirname "$0")/.."
ENV_FILE=".env.local"
TOTAL_STAGES=5

banner "learnaws · claves de OpenAI, Clerk y notificaciones"

# ── 1. OpenAI ─────────────────────────────────────────────────────────────
stage "OpenAI — API key del servidor"
say "Esta key solo genera contenido compartido (banco de preguntas y audio cacheado)."
say "Cada usuario usa su propia key para el tutor y la voz (Ajustes → IA en la app)."
open_url "https://platform.openai.com/api-keys"
step "Create new secret key → nombre: learnaws → Create secret key → copia la clave (sk-…)."
ask_secret OPENAI_API_KEY "Pega la API key:"
code=$(curl -s -o /dev/null -w '%{http_code}' https://api.openai.com/v1/models -H "Authorization: Bearer $OPENAI_API_KEY" || echo 000)
if [[ "$code" == "200" ]]; then
  printf '  %s✓ la clave funciona%s\n' "$GREEN" "$RESET"
else
  warn "OpenAI respondió HTTP $code — revisa la clave (puedes re-ejecutar el wizard)."
fi
write_env OPENAI_API_KEY "$OPENAI_API_KEY"
say ""
note "Recomendado: pon un tope de gasto en tu cuenta (la app además corta a US\$20/mes)."
open_url "https://platform.openai.com/settings/organization/limits"
pause "Enter para seguir"

# ── 2. Clerk app ──────────────────────────────────────────────────────────
stage "Clerk — aplicación y claves"
say "Clerk protege la app: solo tu usuario puede entrar."
open_url "https://dashboard.clerk.com/"
step "Create application → nombre: learnaws → deja Email (y Google si quieres) → Create application."
step "En la app nueva ve a Configure → API keys (o el bloque de Next.js del quickstart)."
ask NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY "Pega la Publishable key (pk_…):"
ask_secret CLERK_SECRET_KEY "Pega la Secret key (sk_…):"
write_env NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY "$NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY"
write_env CLERK_SECRET_KEY "$CLERK_SECRET_KEY"

# ── 3. Your user ──────────────────────────────────────────────────────────
stage "Clerk — tu usuario administrador"
step "En el dashboard de Clerk: Users → Create user → tu email (y contraseña si la pide) → Create."
step "Abre el usuario y copia su User ID (empieza con user_)."
ask ADMIN_USER_IDS "Pega tu User ID (admin; varios separados por coma):"
write_env ADMIN_USER_IDS "$ADMIN_USER_IDS"
step "Registro abierto: Configure → Access mode → Open."
note "Si prefieres cerrar el registro más adelante, cámbialo a Invite-only o Waitlist; no requiere tocar código."
pause "Enter cuando termines"

# ── 4. Push notifications ─────────────────────────────────────────────────
stage "Notificaciones y cifrado"
if [[ -n "$(_existing NEXT_PUBLIC_VAPID_PUBLIC_KEY || true)" && -n "$(_existing VAPID_PRIVATE_KEY || true)" ]]; then
  say "Ya existen claves VAPID en $ENV_FILE; se reutilizan."
  NEXT_PUBLIC_VAPID_PUBLIC_KEY=$(_existing NEXT_PUBLIC_VAPID_PUBLIC_KEY)
  VAPID_PRIVATE_KEY=$(_existing VAPID_PRIVATE_KEY)
else
  say "Generando un par de claves para el recordatorio diario (no tienes que copiar nada)…"
  # stdin pipes into node are flaky in Git Bash on Windows: generate in-process instead.
  keys=$(node -e 'const k=require("web-push").generateVAPIDKeys();console.log(k.publicKey+" "+k.privateKey)')
  NEXT_PUBLIC_VAPID_PUBLIC_KEY=${keys% *}
  VAPID_PRIVATE_KEY=${keys#* }
fi
write_env NEXT_PUBLIC_VAPID_PUBLIC_KEY "$NEXT_PUBLIC_VAPID_PUBLIC_KEY"
write_env VAPID_PRIVATE_KEY "$VAPID_PRIVATE_KEY"
write_env VAPID_SUBJECT "https://learnaws.crafter.run"
if [[ -z "$(_existing ENCRYPTION_KEY || true)" ]]; then
  write_env ENCRYPTION_KEY "$(node -e 'console.log(require("crypto").randomBytes(32).toString("base64"))')"
fi
note "ENCRYPTION_KEY cifra las API keys de los usuarios: no la cambies o tendrán que volver a cargarlas."

# ── 5. Dokploy ────────────────────────────────────────────────────────────
stage "Dokploy — subir las claves y desplegar"
say "Se suben a la app learnaws en tu VPS (los valores no se imprimen)."
if confirm "¿Subir las claves a Dokploy ahora?"; then
  tmp=$(mktemp)
  for k in OPENAI_API_KEY NEXT_PUBLIC_CLERK_PUBLISHABLE_KEY CLERK_SECRET_KEY ADMIN_USER_IDS NEXT_PUBLIC_VAPID_PUBLIC_KEY VAPID_PRIVATE_KEY VAPID_SUBJECT ENCRYPTION_KEY; do
    printf '%s=%s\n' "$k" "$(_existing "$k")" >> "$tmp"
  done
  if node scripts/dokploy-env.mjs "$tmp"; then :; else SKIPPED+=("Subir claves a Dokploy: node scripts/dokploy-env.mjs"); fi
  rm -f "$tmp"
  app_id=$(node -pe 'require("./scripts/dokploy.json").applicationId')
  if confirm "¿Redesplegar la app para aplicar las claves (~3–5 min)?"; then
    vps app deploy "$app_id" --json >/dev/null && printf '  %s✓ deploy lanzado%s → https://learnaws.crafter.run\n' "$GREEN" "$RESET" \
      || SKIPPED+=("Deploy: vps app deploy $app_id")
  fi
else
  SKIPPED+=("Subir claves a Dokploy: vuelve a correr pnpm secrets")
fi
pause "Enter para terminar"

finish
say "Local: pnpm dev → http://localhost:3000 · Producción: https://learnaws.crafter.run"
